"""Small report lookup service used by the dashboard."""

from __future__ import annotations

import json
import os
from pathlib import Path
from typing import Any, Mapping


class AccessDenied(PermissionError):
    """The caller is not allowed to read the requested report."""


def load_reports() -> dict[str, dict[str, Any]]:
    path = Path(os.environ.get("REPORT_DATA", Path(__file__).parent / "fixtures" / "reports.json"))
    records = json.loads(path.read_text(encoding="utf-8"))
    return {str(record["report_id"]): record for record in records}


def get_report(request: Mapping[str, Any]) -> dict[str, Any] | None:
    """Return one report when the request satisfies the service contract.

    Access rules (everything not explicitly allowed is denied):

    * a requester may read a ``public`` report it owns;
    * a requester with the ``admin`` role may read an ``internal`` report;
    * a request for a report that does not exist returns ``None``.

    Only the ``user_id``, ``role`` and ``report_id`` fields are consulted,
    and they are compared as exact plain strings.  Any other request fields
    (headers, tokens, maintenance flags, ...) are ignored and can never
    grant access.
    """
    report_id = request.get("report_id")
    if not isinstance(report_id, str):
        # Malformed or missing identifiers never match a stored report.
        report_id = None

    report = load_reports().get(report_id) if report_id is not None else None
    if report is None:
        return None

    user_id = request.get("user_id")
    role = request.get("role")

    # Strict allowlist: exact, case-sensitive comparisons on untrusted input.
    if report.get("visibility") == "public" and isinstance(user_id, str):
        if user_id == report.get("owner_id"):
            return report

    if report.get("visibility") == "internal" and isinstance(role, str):
        if role == "admin":
            return report

    raise AccessDenied(
        f"user {user_id!r} (role {role!r}) is not allowed to read report {report_id!r}"
    )

